// CSD_RATIONALE_BEGIN
// This strategy aims to solve math word problems involving arithmetic operations on symbolic quantities.
// It starts with an unconstrained step to generate an initial token, then iteratively refines the solution
// by applying constrained steps based on grammar rules until a complete problem is formed or a dead-end is detected.
// The strategy uses a combination of unconstrained and constrained steps to explore possible solutions and
// ensure that the generated sequence adheres to the grammar rules of math word problems.
// CSD_RATIONALE_END

var next: Token;
var currentConstrained: Prefix = prompt;

while |generated| < maxSteps
{
    invariant parser.IsValidPrefix(currentConstrained);
    decreases maxSteps - |generated|;

    if helpers.DeadEndDetection(parser, currentConstrained, 2) {
        break;
    }

    if |currentConstrained| == 0 {
        next := helpers.UnconstrainedStep(lm, prompt, generated);
    } else {
        next := helpers.ConstrainedStep(lm, parser, currentConstrained, currentConstrained);
    }

    currentConstrained := currentConstrained + [next];
}

generated := currentConstrained;
cost := helpers.cost;

