// This strategy alternates between unconstrained and constrained steps to generate a sequence that adheres to grammar rules.
// It ensures that the generated sequence remains within the grammar constraints until the end-of-sequence token is reached.
// CSD_RATIONALE_END

var next: Token;
var currentConstrained: Prefix = prompt;
var steps: nat = 0;
var insideConstrained: bool = false;

while |generated| < maxSteps
{
    invariant parser.IsValidPrefix(currentConstrained);
    decreases maxSteps - steps, if insideConstrained then 1 else 0;

    if helpers.DeadEndDetection(parser, currentConstrained, 2) {
        break;
    }

    if insideConstrained {
        next := helpers.ConstrainedStep(lm, parser, currentConstrained, currentConstrained);
    } else {
        next := helpers.UnconstrainedStep(lm, prompt, generated);
    }

    generated := generated + [next];
    steps := steps + 1;
    insideConstrained := !insideConstrained;
}

cost := helpers.cost;

